steps.sampleSolution:
const alunos = [
  { nome: "Bia", nota: 9 },
  { nome: "Léo", nota: 5 },
];
const nomesAprovados = alunos
  .filter((a) => a.nota >= 7)
  .map((a) => a.nome);
console.log(nomesAprovados);
